scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gLastJob = "조회";
scwin.vScrenID = 'ULDSTF31000.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    dts_C_CodeChrgEmpNo.DataID = "/CodeAction.do?method=listEmpNo&DEP_CD=" + js_dep_cd + "&TEAM_ID=" + js_team + "&ROLL_CD=09&For=C";
    dts_C_CodeChrgEmpNo.Reset();
    dts_C_CodeEmpNo.DataID = "/CodeAction.do?method=listEmpNo&DEP_CD=" + js_dep_cd + "&TEAM_ID=" + js_team + "&ROLL_CD=03&For=C";
    dts_C_CodeEmpNo.Reset();
    dts_R_CodeChrgEmpNo.DataID = "/CodeAction.do?method=listEmpNo&DEP_CD=" + js_dep_cd + "&TEAM_ID=" + js_team + "&ROLL_CD=09&For=R";
    dts_R_CodeChrgEmpNo.Reset();
    dts_R_CodeEmpNo.DataID = "/CodeAction.do?method=listEmpNo&DEP_CD=" + js_dep_cd + "&TEAM_ID=" + js_team + "&ROLL_CD=03&For=R";
    dts_R_CodeEmpNo.Reset();
    //alert("call");	

    //팀장콤보에 팀원 추가.(YSH, 2008/08/26)
    for (var i = 1; i <= dts_C_CodeEmpNo.getTotalRow(); i++) {
        if ("" != dts_C_CodeEmpNo.getCellData(i, 1)) {
            dts_C_CodeChrgEmpNo.insertRow();
            //alert(dts_C_CodeChrgEmpNo.CountRow);
            var crow = dts_C_CodeChrgEmpNo.getTotalRow();
            dts_C_CodeChrgEmpNo.setCellData(crow, "VALUE", dts_C_CodeEmpNo.getCellData(i, 1));
            dts_C_CodeChrgEmpNo.setCellData(crow, "TEXT", dts_C_CodeEmpNo.getCellData(i, 2));
        }
    }
    dts_C_CodeChrgEmpNo.setRowPosition(1, 0);
    for (var i = 1; i <= dts_R_CodeEmpNo.getTotalRow(); i++) {
        if ("" != dts_R_CodeEmpNo.getCellData(i, 1)) {
            dts_R_CodeChrgEmpNo.insertRow();
            //alert(dts_C_CodeChrgEmpNo.CountRow);
            var crow = dts_R_CodeChrgEmpNo.getTotalRow();
            dts_R_CodeChrgEmpNo.setCellData(crow, "VALUE", dts_R_CodeEmpNo.getCellData(i, 1));
            dts_R_CodeChrgEmpNo.setCellData(crow, "TEXT", dts_R_CodeEmpNo.getCellData(i, 2));
        }
    }
    dts_R_CodeChrgEmpNo.setRowPosition(1, 0);

    // 달력
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    var yyyyNext = parseInt(ToDay.getYear(), 10) + 1;
    var mm = parseInt(ToDay.getMonth(), 10) + 1;
    var str = "";
    for (var i = yyyyNext; i >= 1998; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    //alert(str);
    cmb_YYYY.CBData = str;
    $c.stf.setObjectValue(cmb_YYYY, yyyy);
    // 월
    $c.stf.setObjectValue(cmb_MM, $c.ut.lpad(mm, 2, "0"));
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(edt_Date) == "") {
        $c.win.alert("[일자]를 입력하세요.");
        edt_Date.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_ChrgEmpNo1) == "") {
        $c.win.alert("[팀장]을 선택하세요.");
        cmb_ChrgEmpNo1.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_EmpNo1) == "") {
        $c.win.alert("[사원]을 선택하세요.");
        cmb_EmpNo1.focus();
        return;
    }
    trs_Save.Action = "/PersonOnDuty.do?method=registerPersonOnDuty" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_C_All)";
    trs_Save.Post();
};
scwin.fn_SetHeader = function() {
    var h = "DUTY_DD:string,DISCLS_DUTY_CHRG_EMP_NO:string,DISCLS_DUTY_EMP_NO:string,MKT_ID:string,SEQ:string,EMP_NO:string";
    //dts_C_All.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_C_All.insertRow();
    dts_C_All.setCellData(1, "MKT_ID", js_market);
    dts_C_All.setCellData(1, "EMP_NO", js_emp_no);
    if (js_belngdepcd == '2400' || js_dep_cd == '2400') {
        $c.cm.setColumnProp(grd_List, "DISCLS_DUTY_CHRG_EMP_NM", "Name", "오전");
        $c.cm.setColumnProp(grd_List, "DISCLS_DUTY_EMP_NM", "Name", "오후");
        txtTL01.setValue("오전");
        txtTm01.setValue("오후");
        txtTL02.setValue("오전");
        txtTm02.setValue("오후");
    }
};
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_List);
    var ChrgEmpNo = $c.cp.valueOfIndex(cmb_ChrgEmpNo2, "VALUE", cmb_ChrgEmpNo2.getSelectedIndex());
    var EmpNo = $c.cp.valueOfIndex(cmb_EmpNo2, "VALUE", cmb_EmpNo2.getSelectedIndex());
    var SDate = edt_SDate.getValue();
    var EDate = edt_EDate.getValue();
    var url = "/PersonOnDuty.do?method=searchPersonOnDuty&ChrgEmpNo=" + ChrgEmpNo;
    url += "&EmpNo=" + EmpNo;
    url += "&SDate=" + SDate;
    url += "&EDate=" + EDate;
    if (js_dep_cd == "2430") {
        url += "&GDUTY=";
    } else {
        url += "&GDUTY=" + js_gduty;
    }
    url += "&MKT_ID=" + js_market;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_PersonOnDutyList.DataID = encodeURI(url); //"/PersonOnDuty.do?method=listPersonOnDuty";
    dts_PersonOnDutyList.Reset();
};
scwin.fn_CalSearch = function() {
    var YYYYMM = $c.stf.getObjectValue(cmb_YYYY) + $c.stf.getObjectValue(cmb_MM);
    var url = "/PersonOnDuty.do?method=listCalSearch";
    url += "&YYYYMM=" + YYYYMM;
    if (js_dep_cd == "2430") {
        url += "&GDUTY=";
    } else {
        url += "&GDUTY=" + js_gduty;
    }
    url += "&MKT_ID=" + js_market;
    dts_Cal.DataID = encodeURI(url);
    dts_Cal.Reset();
};
scwin.fn_delete = function(GridID, row, colid) {
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    if (colid == "DEL_FUNC") {
        var res = window.confirm("삭제하시겠습니까?");
        if (res) {
            scwin.gLastJob = "삭제";
            var url = "/PersonOnDuty.do?method=deleteDuty";
            url += "&DEL_EMP_NO=" + js_emp_no;
            url += "&SEQ=" + objDataID.getCellData(row, "SEQ");
            url += "&SCREN_ID=" + scwin.vScrenID;
            url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
            dts_PersonOnDutyList.DataID = encodeURI(url); //"/PersonOnDuty.do?method=listPersonOnDuty";
            dts_PersonOnDutyList.Reset();
            scwin.fn_Search();
        }
    }
};
scwin.alert_error2 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                //'0' 임의로 떨군 INFO 메시지
                $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                //기존 에러 메시지
                $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
scwin.dts_PersonOnDutyList_OnLoadCompleted = function(rowcount) {
    if (scwin.gLastJob == "삭제") {
        var msg = $c.stf.getMessageParam("MSG-A001", "삭제");
        $c.win.alert(msg);
        scwin.gLastJob = "";
    }
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.img_Date_onclick = function() {
    popUpCalendar2(edt_Date);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_C_CodeChrgEmpNo_OnLoadCompleted = function(rowcount) {
    //alert(dts_C_CodeChrgEmpNo.Text);

    //alert('dts_C_CodeChrgEmpNo.OnLoadCompleted('+rowcount+')');

    //FillGridHeaderTotalCnt(rowcount, grd_List);

};
scwin.btn_Save_onclick = function() {
    scwin.fn_CheckForm();
};
scwin.trs_Save_OnFail = function() {
    scwin.alert_error2(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    var prev_team_jang = $c.stf.getObjectValue(cmb_ChrgEmpNo1);
    var prev_team_one = $c.stf.getObjectValue(cmb_EmpNo1);
    var prev_date = $c.stf.getObjectValue(edt_Date);
    $c.win.alert("저장 성공");
    // 목록 다시 조회
    scwin.fn_Search();
    scwin.fn_CalSearch();
    scwin.fn_SetHeader();
    $c.stf.setObjectValue(cmb_ChrgEmpNo1, prev_team_jang);
    $c.stf.setObjectValue(cmb_EmpNo1, prev_team_one);
    $c.stf.setObjectValue(edt_Date, prev_date);
};
scwin.dts_C_All_OnLoadError = function() {
    $c.stf.alert_error(dts_C_All);
};
scwin.btn_CalSearch_onclick = function() {
    scwin.fn_CalSearch();
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_delete(grd_List, row, colid);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_3);
    scwin.fn_SetHeader();
    scwin.fn_SetCode();
    //alert("js_duty_chrg=" + js_duty_chrg + ", js_duty=" + js_duty);

    $c.cm.setColumnProp(grd_calendar, 'day1', 'Multiline', true);
    $c.cm.setColumnProp(grd_calendar, 'day2', 'Multiline', true);
    $c.cm.setColumnProp(grd_calendar, 'day3', 'Multiline', true);
    $c.cm.setColumnProp(grd_calendar, 'day4', 'Multiline', true);
    $c.cm.setColumnProp(grd_calendar, 'day5', 'Multiline', true);
    $c.cm.setColumnProp(grd_calendar, 'day6', 'Multiline', true);
    $c.cm.setColumnProp(grd_calendar, 'day7', 'Multiline', true);
};
